#ifndef __NOAH_GAMETEXT_H__
#define __NOAH_GAMETEXT_H__

// The texts Noah's Ark shows (dialogs, tutorial boxes, rank names, labels) are hard-coded in the original's
// exe; there is no string file. port: by the user's decision (2026-10-19) no game text is in the repository:
// the port reads every text at start-up from the player's own executable, by address, and a mod or language
// pack can replace any of them.
//
// - GameTextTable.inc (generated by games/noahsark/tools/make_gametext.py) lists each string's address in
//   the 1.1 game image, its length and a hash: no text.
// - LoadGameTexts() finds WinNoah.exe in the game folder, reads each text at its address and checks length
//   and hash. A text that does not match (another version of the exe) stays empty and is logged.
// - Code names a text by its address in the original: GT(0x00495998). Overrides: any string property named
//   GT_<8 hex digits> (e.g. <String id="GT_00495998">...</String> in properties/texts.xml, from the game folder
//   or a mod) replaces the text read from the exe.

#include "Common.h"

namespace Sexy
{

// Reads the texts from the game folder's executable and applies the string-property overrides. Returns
// false when the executable is missing or no text matched (the texts are then empty or overrides only).
bool				LoadGameTexts();
// The text the original keeps at theVA; "" for an address that is not in the table
const SexyString&	GameText(unsigned int theVA);

#define GT(theVA) (::Sexy::GameText(theVA))
#define GTC(theVA) (::Sexy::GameText(theVA).c_str())

}

#endif
